const $=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const fmt=n=>String(n).replace('-','−');const storage={get(k){try{return localStorage.getItem('fondasi-factor-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-factor-'+k,v);return true}catch{return false}}};function svg(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;$('#diagram').append(e)}function area(){const k=Number($('#factor').value),x=Number($('#x').value),b=Number($('#b').value);$('#factor-out').value=k;$('#x-out').value=x;$('#b-out').value=b;$('#diagram').replaceChildren();const unit=38,start=65,top=60,h=k*unit;svg('rect',{x:start,y:top,width:x*unit,height:h,fill:'#b9ceae',stroke:'#244d40','stroke-width':2});svg('rect',{x:start+x*unit,y:top,width:b*unit,height:h,fill:'#e4bcaa',stroke:'#244d40','stroke-width':2});for(const [tx,ty,label]of [[start+x*unit/2,top-18,`x = ${x}`],[start+(x+b/2)*unit,top-18,`b = ${b}`],[start-30,top+h/2,`k=${k}`],[start+x*unit/2,top+h/2,`${k*x}`],[start+(x+b/2)*unit,top+h/2,`${k*b}`]])svg('text',{x:tx,y:ty,'text-anchor':'middle'},label);$('#area-equation').textContent=`${k}x + ${k*b} = ${k}(x + ${b})`;$('#area-feedback').textContent=`Pada x = ${x}, jumlah luasnya ${k*x} + ${k*b} = ${k*(x+b)}. Bentuk faktor memberi ${k} × (${x} + ${b}) = ${k*(x+b)}. Tinggi bersama ${k} menjadi faktor di luar kurung.`}for(const id of ['#factor','#x','#b'])$(id).addEventListener('input',area);area();const targets=[{B:5,C:6,name:'x² + 5x + 6'},{B:-1,C:-6,name:'x² − x − 6'},{B:4,C:4,name:'x² + 4x + 4'}];function bracket(n){return n===0?'x':`x ${n<0?'−':'+'} ${Math.abs(n)}`}function poly(B,C){return 'x²'+(B===0?'':` ${B<0?'−':'+'} ${Math.abs(B)===1?'':Math.abs(B)}x`)+(C===0?'':` ${C<0?'−':'+'} ${Math.abs(C)}`)}function pair(){const p=Number($('#p').value),q=Number($('#q').value),t=targets[Number($('#target').value)],B=p+q,C=p*q;$('#p-out').value=fmt(p);$('#q-out').value=fmt(q);$('#expanded').textContent=`(${bracket(p)})(${bracket(q)}) = ${poly(B,C)}`;const ok=B===t.B&&C===t.C;$('#pair-feedback').textContent=`p + q = ${fmt(B)}; pq = ${fmt(C)}. Target ${t.name} memerlukan jumlah ${fmt(t.B)} dan hasil kali ${fmt(t.C)}. `+(ok?'Cocok! Kedua syarat terpenuhi. Kalikan kembali untuk memeriksanya.':'Belum cocok. Cari pasangan yang memenuhi kedua syarat sekaligus.')}for(const id of ['#p','#q'])$(id).addEventListener('input',pair);$('#target').addEventListener('change',pair);pair();$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='correct'?'Tepat. Membuka kurung memberi 3 × 2x + 3 × 3 = 6x + 9.':'Kalikan kembali untuk memeriksa. Faktor 3 harus menghasilkan 6x dan 9. Maka isi kurung adalah 2x + 3.'});
const qs=[{t:'Pada 8x + 12 = 4(2x + □), berapa isi kotak?',n:3,d:1,h:'Bilangan dalam kurung dikalikan 4 untuk menghasilkan 12.',why:'12 dibagi 4 adalah 3. Periksa: 4 × 3 = 12.'},{t:'Pada 5x² + 10x = 5x(x + □), berapa isi kotak?',n:2,d:1,h:'Faktor 5x harus mengalikan suku kedua menjadi 10x.',why:'5x × 2 = 10x, sehingga isi kotaknya 2.'},{t:'Pada x² + 5x + 6 = (x + 2)(x + □), berapa isi kotak?',n:3,d:1,h:'Cari q dengan 2 + q = 5 dan 2q = 6.',why:'q = 3 memenuhi jumlah 5 dan hasil kali 6.'},{t:'Pada x² − x − 6 = (x − 3)(x + □), berapa isi kotak?',n:2,d:1,h:'Cari q dengan −3 + q = −1 dan −3q = −6.',why:'q = 2 memenuhi kedua syarat.'},{t:'Pada x² − 16 = (x − □)(x + □), kedua kotak berisi bilangan positif yang sama. Berapa bilangannya?',n:4,d:1,h:'16 adalah kuadrat bilangan positif berapa?',why:'16 = 4², sehingga x² − 16 = (x − 4)(x + 4). '},{t:'Pada 3x + 6 = 3(x + □), berapa isi kotak?',n:2,d:1,h:'Kalikan kembali: 3 kali kotak harus bernilai 6.',why:'3 × 2 = 6. Jadi isi kotaknya 2.'},{t:'Jika x = 2, berapa nilai (x + 2)(x + 3)?',n:20,d:1,h:'Hitung kedua kurung, lalu kalikan.',why:'(2 + 2)(2 + 3) = 4 × 5 = 20. Bentuk x² + 5x + 6 juga bernilai 20.'}];const solved=new Set();function progress(){$('#progress').textContent=`${solved.size} dari 8 latihan telah dijawab dengan tepat.`}function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, satu bilangan</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya 3" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(form=>form.addEventListener('submit',ev=>{ev.preventDefault();const i=Number(form.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis satu bilangan. Jika memakai pecahan, penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Kalikan kembali faktor-faktornya dan bandingkan setiap suku dengan bentuk awal.';if(ok)solved.add(i);progress()}));$('#check-condition').addEventListener('click',()=>{const v=document.querySelector('[name=condition]:checked')?.value,ok=v==='restricted';$('#condition-feedback').className='feedback '+(ok?'correct':'incorrect');$('#condition-feedback').textContent=!v?'Pilih satu jawaban terlebih dahulu.':ok?'Tepat. x ≠ 3 tetap berlaku karena bentuk awal memiliki penyebut x − 3.':'Periksa penyebut bentuk awal x − 3. Nilai x = 3 membuatnya nol dan tetap tidak diizinkan setelah penyederhanaan.';if(ok)solved.add(7);progress()});$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin jika ingin menyimpannya.'});function complete(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')complete();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');complete();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu dapat kembali berlatih kapan saja.':'Selesai. Kemajuan belum dapat disimpan pada peramban ini.'});
